// HasOauthApp applies the HasEdge predicate on the "oauthApp" edge.
func HasOauthApp() predicate.OAuthAuthorization {
	return predicate.OAuthAuthorization(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OauthAppTable, OauthAppColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOauthAppWith applies the HasEdge predicate on the "oauthApp" edge with a given conditions (other predicates).
func HasOauthAppWith(preds ...predicate.OAuthApp) predicate.OAuthAuthorization {
	return predicate.OAuthAuthorization(func(s *sql.Selector) {
		step := newOauthAppStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

